INSERT INTO `emergency_contacts` (`id`, `number`, `name_en`, `name_ta`, `desc_en`, `desc_ta`) VALUES
(1, '100', 'Police Control Room', 'காவல் கட்டுப்பாட்டு அறை', 'Immediate emergency police assistance citywide.', 'மாநகரம் முழுவதும் உடனடி அவசர காவல் உதவி.'),
(2, '112', 'National Emergency Support', 'தேசிய அவசர உதவி எண்', 'Unified emergency services (Police, Fire, Ambulance).', 'ஒருங்கிணைந்த அவசர கால சேவைகள் (காவல், தீயணைப்பு, ஆம்புலன்ஸ்).'),
(3, '1930', 'Cyber Crime Helpline', 'சைபர் குற்றத் தடுப்பு உதவி எண்', 'Report online financial fraud within the golden hour.', 'ஆன்லைன் நிதி மோசடிகளை உடனடியாகத் தெரிவிக்கவும்.'),
(4, '1091', 'Women Helpline Desk', 'பெண்கள் உதவி மையம்', 'Safety assistance & rescue services for women in distress.', 'பாதிப்பிற்குள்ளாகும் பெண்களுக்கான பாதுகாப்பு உதவி.'),
(5, '1098', 'Child Helpline Service', 'குழந்தைகள் உதவி மையம்', 'Emergency protection & rescue for children.', 'குழந்தைகளுக்கான அவசர பாதுகாப்பு மற்றும் மீட்புப் பணிகள்.');
INSERT INTO `department_links` (`id`, `name_en`, `name_ta`, `url`, `desc_en`, `desc_ta`) VALUES
(1, 'Commissioner Office', 'ஆணையர் அலுவலகம்', 'https://gcp.tn.gov.in', 'Official executive portal of the Greater Chennai Police Commissionerate.', 'சென்னை பெருநகர காவல் ஆணையரகத்தின் அதிகாரப்பூர்வ இணையதளம்.'),
(2, 'Cyber Crime Reporting Portal', 'சைபர் குற்ற புகார் இணையதளம்', 'https://cybercrime.gov.in', 'National portal for reporting all types of cyber fraud and online harassment.', 'அனைத்து வகையான சைபர் குற்றங்கள் மற்றும் ஆன்லைன் தொல்லைகளைப் புகாரளிப்பதற்கான தேசிய தளம்.'),
(3, 'Women Safety Wing', 'பெண்கள் பாதுகாப்பு பிரிவு', 'https://gcp.tn.gov.in/womensafety', 'Dedicated services, safety hotlines, and support resources for women.', 'பெண்களுக்கான பிரத்யேக சேவைகள், பாதுகாப்பு மற்றும் ஆதரவு ஆதாரங்கள்.'),
(4, 'Passport Verification', 'கடவுச்சீட்டு சரிபார்ப்பு தளம்', 'https://passportindia.gov.in', 'Official portal to check status of passport police verification progress.', 'கடவுச்சீட்டு காவல் சரிபார்ப்பு முன்னேற்றத்தின் நிலையை சரிபார்க்கும் தளம்.'),
(5, 'Lost Document Reporting', 'இழந்த ஆவணங்கள் அறிக்கை தளம்', 'https://eservices.tnpolice.gov.in', 'Report lost documents and obtain a digitally signed police report.', 'இழந்த ஆவணங்களைப் புகாரளித்து, டிஜிட்டல் கையொப்பமிட்ட காவல் அறிக்கையைப் பெற.');
INSERT INTO `web_stories` (`id`, `title_en`, `title_ta`, `cover_image`, `slides_json`, `category_en`, `category_ta`, `status`, `active`, `views_count`, `created_at`, `news_slug`) VALUES
(1, '300 GCP Officers Honored with Chief Minister\'s Police Medal', '300 சென்னை பெருநகர காவலர்களுக்கு முதலமைச்சரின் காவல் பதக்கம் வழங்கி கௌரவம்', '/uploads/upload_1782285632960.png', '[{"image":"/uploads/upload_1782285632960.png","caption_en":"300 Greater Chennai Police personnel received the prestigious TN Chief Minister\'s Police Medal.","caption_ta":"300 சென்னை பெருநகர காவல் பணியாளர்களுக்கு தமிழ்நாடு முதலமைச்சரின் காவல் பதக்கம் வழங்கப்பட்டது."},{"image":"/images/slider_4.jpg","caption_en":"Commendation certificates awarded for exceptional devotion to duty and administrative excellence.","caption_ta":"சிறந்த கடமை உணர்வு மற்றும் நிர்வாக சிறப்பிற்காக பாராட்டு சான்றிதழ்கள் வழங்கப்பட்டன."},{"image":"/images/slider_6.jpg","caption_en":"Greater Chennai Police continues to uphold the highest standards of public service.","caption_ta":"சென்னை பெருநகர காவல் துறை பொதுச் சேவையில் உயர்ந்த தரத்தைப் பேணுகிறது."}]', 'Awards', 'விருதுகள்', 'active', 1, 142, '2026-07-03T10:00:00.000Z', 'police-medal-award-ceremony'),
(2, 'Singappen Special Women Patrol Force Unit Launched', 'சென்னை நகரில் சிங்கப்பெண் சிறப்பு பெண்கள் பாதுகாப்பு ரோந்து படை தொடக்கம்', '/images/slider_2.jpg', '[{"image":"/images/slider_2.jpg","caption_en":"Singappen Initiative: All-women mobile patrolling squads deployed in high-density areas.","caption_ta":"சிங்கப்பெண் திட்டம்: பெண்கள் அதிகம் கூடும் இடங்களில் 24 மணி நேர ரோந்து பணி."},{"image":"/uploads/upload_1782285477484.png","caption_en":"Ensuring safe transit, immediate response, and zero tolerance for harassment.","caption_ta":"பாதுகாப்பான பயணம், உடனடி நடவடிக்கை மற்றும் பெண்களுக்கு எதிரான குற்றங்களுக்கு முற்றுப்புள்ளி."},{"image":"/images/gcp_logo.png","caption_en":"Call Women Helpline 1091 or National Emergency 112 for immediate assistance.","caption_ta":"அவசர உதவிக்கு பெண்கள் உதவி எண் 1091 அல்லது 112 ஐ தொடர்பு கொள்ளவும்."}]', 'Women Safety', 'பெண்கள் பாதுகாப்பு', 'active', 1, 215, '2026-07-03T10:05:00.000Z', 'singappen-womens-safety-initiative'),
(3, 'Dr. A. Amalraj IPS Takes Charge as Commissioner of Police, Greater Chennai', 'டாக்டர் ஏ. அமல்ராஜ் ஐபிஎஸ் சென்னை பெருநகர காவல் ஆணையராக பொறுப்பேற்றார்', '/images/amalraj_portrait.png', '[{"image":"/images/amalraj_portrait.png","caption_en":"Dr. A. Amalraj IPS of 1996 batch takes command as Commissioner of Police, Greater Chennai.","caption_ta":"1996 பேட்ச் ஐபிஎஸ் அதிகாரி டாக்டர் ஏ. அமல்ராஜ் சென்னை பெருநகர காவல் ஆணையராக பொறுப்பேற்றார்."},{"image":"/uploads/upload_1782285932912.png","caption_en":"Emphasizing modern human resource management, scientific analytics, and proactive policing.","caption_ta":"நவீன மனிதவள மேலாண்மை மற்றும் அறிவியல் பகுப்பாய்வு முறைகளுக்கு முக்கியத்துவம்."},{"image":"/uploads/upload_1782285750226.png","caption_en":"Pledged dedicated public safety, crime prevention, and community outreach.","caption_ta":"பொதுமக்கள் பாதுகாப்பு மற்றும் சமூக தொடர்புகளுக்கு முன்னுரிமை அளிக்கப்படும் என உறுதி."}]', 'Police Update', 'காவல் நிர்வாகம்', 'active', 1, 389, '2026-07-03T10:10:00.000Z', 'amalraj-posted-commissioner'),
(4, 'Kaaval Karangal Rescues Homeless & Reunites Families', 'காவல் கரங்கள் திட்டம் மூலம் ஆதரவற்ற முதியவர்கள் மீட்பு மற்றும் குடும்ப இணைப்பு', '/images/slider_6.jpg', '[{"image":"/images/slider_6.jpg","caption_en":"Greater Chennai Police\'s Kaaval Karangal wing rescues abandoned senior citizens.","caption_ta":"சென்னை பெருநகர காவல்துறையின் காவல் கரங்கள் பிரிவு ஆதரவற்ற முதியவர்களை மீட்கிறது."},{"image":"/images/slider_2.jpg","caption_en":"Providing medical aid, shelter homes, and reuniting missing persons with families.","caption_ta":"மருத்துவ உதவி, தங்குமிடம் மற்றும் காணாமல் போனவர்களை குடும்பத்தினருடன் சேர்த்தல்."}]', 'Community Outreach', 'சமூக உதவி', 'active', 1, 178, '2026-07-03T10:15:00.000Z', 'kaaval-karangal-rescue-drive'),
(5, 'Cyber Safety Alert: Report Financial Scams on Helpline 1930', 'சைபர் விழிப்புணர்வு: ஆன்லைன் நிதி மோசடிகளை 1930 எண்ணில் தெரிவிக்கவும்', '/images/slider_4.jpg', '[{"image":"/images/slider_4.jpg","caption_en":"Never share OTP, PIN, CVV, or banking credentials with unknown callers.","caption_ta":"OTP, PIN அல்லது வங்கி விவரங்களை யாருடனும் ஒருபோதும் பகிர வேண்டாம்."},{"image":"/images/gcp_logo.png","caption_en":"Report financial fraud within 1 hour to Helpline 1930 or cybercrime.gov.in.","caption_ta":"நிதி மோசடியை 1 மணி நேரத்திற்குள் 1930 உதவி எண் அல்லது cybercrime.gov.in இல் தெரிவிக்கவும்."}]', 'Cyber Safety', 'சைபர் பாதுகாப்பு', 'active', 1, 294, '2026-07-03T10:20:00.000Z', 'cyber-crime-advisory-1930');
