INSERT INTO `citizen_service_categories` (`id`, `name`, `name_en`, `name_ta`, `slug`, `description`, `description_en`, `description_ta`, `display_order`, `is_active`) VALUES
(1, 'Report & Complaints', 'Report & Complaints', 'புகார்கள் மற்றும் அறிக்கைகள்', 'report-complaints', 'Register complaints, online FIR, track CSR and report incidents online.', 'Register complaints, online FIR, track CSR and report incidents online.', 'காவல் புகார் பதிவு, ஆன்லைன் முதல் தகவல் அறிக்கை மற்றும் சிஎஸ்ஆர் மனு நிலை அறிய.', 1, 1),
(2, 'Verification Services', 'Verification Services', 'சரிபார்ப்பு சேவைகள்', 'verification-services', 'Police clearance certificate, passport verification, tenant and employee verification.', 'Police clearance certificate, passport verification, tenant and employee verification.', 'தடையின்மை சான்றிதழ், பாஸ்போர்ட் சரிபார்ப்பு, வாடகைதாரர் மற்றும் பணியாளர் சரிபார்ப்பு.', 2, 1),
(3, 'Traffic Services', 'Traffic Services', 'போக்குவரத்து சேவைகள்', 'traffic-services', 'Pay traffic e-challan, check vehicle details, towed vehicle finder and traffic diversions.', 'Pay traffic e-challan, check vehicle details, towed vehicle finder and traffic diversions.', 'மின்-செல்லான் கட்டணம் செலுத்துதல், வாகன விவரங்கள் மற்றும் போக்குவரத்து வழிகாட்டல்கள்.', 3, 1),
(4, 'Citizen & Public Safety', 'Citizen & Public Safety', 'பொதுமக்கள் பாதுகாப்பு', 'citizen-public-safety', 'Senior citizen registration, women safety, child helpline and nearest police station finder.', 'Senior citizen registration, women safety, child helpline and nearest police station finder.', 'மூத்த குடிமக்கள் பதிவு, பெண்கள் பாதுகாப்பு, குழந்தைகள் உதவி மற்றும் காவல் நிலைய வழிகாட்டி.', 4, 1),
(5, 'Permissions & Special Services', 'Permissions & Special Services', 'அனுமதிகள் மற்றும் சிறப்பு சேவைகள்', 'permissions-special-services', 'Permissions for loudspeakers, public meetings, film shooting and arms license renewal.', 'Permissions for loudspeakers, public meetings, film shooting and arms license renewal.', 'ஒலிபெருக்கி, பொதுக்கூட்டம், திரைப்பட படப்பிடிப்பு மற்றும் துப்பாக்கி உரிம அனுமதிகள்.', 5, 1);
INSERT INTO `citizen_services` (`id`, `category_id`, `service_name`, `service_name_en`, `service_name_ta`, `description`, `description_en`, `description_ta`, `icon`, `external_url`, `display_order`, `is_active`, `is_featured`, `open_in_new_tab`, `updated_by`, `updated_at`) VALUES
(1, 1, 'File a Police Complaint', 'File a Police Complaint', 'காவல் புகார் பதிவு செய்தல்', 'Report an incident or submit a police complaint online through the state e-services portal.', 'Report an incident or submit a police complaint online through the state e-services portal.', 'சம்பவம் அல்லது அவசர புகார்களை இணையவழியாக உடனடியாக பதிவு செய்து ஒப்புகை பெறவும்.', 'FileText', 'https://eservices.tnpolice.gov.in/', 1, 1, 1, 1, NULL, NULL),
(2, 1, 'Online FIR / FIR Status', 'Online FIR / FIR Status', 'ஆன்லைன் முதல் தகவல் அறிக்கை / நிலை', 'Access registered First Information Reports (FIR) and download official copies online.', 'Access registered First Information Reports (FIR) and download official copies online.', 'பதிவு செய்யப்பட்ட முதல் தகவல் அறிக்கைகளை (FIR) பார்வையிடவும் மற்றும் நகல் பதிவிறக்கவும்.', 'FileCheck', 'https://eservices.tnpolice.gov.in/', 2, 1, 0, 1, 'Digital_TN_GovMaster', '2026-09-07T11:27:00.433Z'),
(3, 1, 'CSR Status', 'CSR Status', 'சி.எஸ்.ஆர் (CSR) மனு நிலை அறிய', 'Track the real-time status and inquiry updates of your Community Service Register receipt.', 'Track the real-time status and inquiry updates of your Community Service Register receipt.', 'காவல் நிலையத்தில் பெறப்பட்ட சி.எஸ்.ஆர் மனுவின் தற்போதைய விசாரணை நிலையை அறியவும்.', 'ClipboardCheck', 'https://eservices.tnpolice.gov.in/', 3, 1, 1, 1, NULL, NULL),
(4, 1, 'Lost Article Report', 'Lost Article Report', 'காணாமல் போன பொருட்கள் புகார் அறிக்கை', 'Report lost documents, identity cards, valuables or mobile devices to obtain digital report.', 'Report lost documents, identity cards, valuables or mobile devices to obtain digital report.', 'சான்றிதழ்கள், ஆவணங்கள் அல்லது உடமைகள் தொலைந்தால் டிஜிட்டல் அறிக்கை பெற பதிவு செய்யவும்.', 'PackageSearch', 'https://eservices.tnpolice.gov.in/', 4, 1, 1, 1, NULL, NULL),
(5, 1, 'Missing Person Report', 'Missing Person Report', 'காணாமல் போன நபர்கள் பற்றிய அறிக்கை', 'View listings of missing persons, track search bulletins or report missing individuals.', 'View listings of missing persons, track search bulletins or report missing individuals.', 'காணாமல் போனவர்கள் குறித்த விவரங்களை பதிவு செய்யவும் மற்றும் தேடல் அறிக்கைகளை காணவும்.', 'UserSearch', 'https://eservices.tnpolice.gov.in/', 5, 1, 0, 1, NULL, NULL),
(6, 1, 'Missing / Stolen Mobile Report', 'Missing / Stolen Mobile Report', 'காணாமல் போன / திருடப்பட்ட செல்போன் புகார்', 'Block and track lost or stolen mobile handsets nationwide via CEIR Central Equipment Identity Register.', 'Block and track lost or stolen mobile handsets nationwide via CEIR Central Equipment Identity Register.', 'தொலைந்த அல்லது திருடப்பட்ட செல்போன்களை முடக்கவும் மற்றும் கண்டறியவும் (CEIR வசதி).', 'Smartphone', 'https://ceir.sancharsaathi.gov.in/', 6, 1, 0, 1, NULL, NULL),
(7, 1, 'Cyber Crime Complaint', 'Cyber Crime Complaint', 'இணையவழி குற்றங்கள் / நிதி மோசடி புகார்', 'Report online financial fraud, cyber threats, phishing and social media harassment.', 'Report online financial fraud, cyber threats, phishing and social media harassment.', 'ஆன்லைன் பண மோசடி, இணையவழி அச்சுறுத்தல்கள் மற்றும் சைபர் குற்றங்களை உடனடியாக பதிவு செய்க.', 'ShieldAlert', 'https://cybercrime.gov.in/', 7, 1, 1, 1, NULL, NULL),
(8, 1, 'Report Traffic Violation', 'Report Traffic Violation', 'போக்குவரத்து விதிமீறல் புகார் அளித்தல்', 'Submit public reports with photos or video of dangerous driving and road traffic violations.', 'Submit public reports with photos or video of dangerous driving and road traffic violations.', 'ஆபத்தான முறையில் வாகனம் ஓட்டுதல் மற்றும் போக்குவரத்து விதிமீறல்களை படங்களுடன் தெரிவிக்கவும்.', 'CarFront', 'https://gctp.in/', 8, 1, 0, 1, NULL, NULL),
(9, 2, 'Police Clearance Certificate', 'Police Clearance Certificate', 'காவல்துறை தடையின்மை சான்றிதழ் (PCC)', 'Apply for an official Police Clearance Certificate (PCC) for employment, emigration or visa.', 'Apply for an official Police Clearance Certificate (PCC) for employment, emigration or visa.', 'வேலைவாய்ப்பு, வெளிநாட்டு பயணம் மற்றும் விசா தேவைகளுக்கான காவல்துறை தடையில்லா சான்றிதழ்.', 'BadgeCheck', 'https://eservices.tnpolice.gov.in/', 9, 1, 1, 1, NULL, NULL),
(10, 2, 'Passport Verification Status', 'Passport Verification Status', 'பாஸ்போர்ட் சரிபார்ப்பு நிலை', 'Track the status of your police verification report for Indian passport application.', 'Track the status of your police verification report for Indian passport application.', 'உங்கள் பாஸ்போர்ட் விண்ணப்பத்திற்கான காவல்துறை சரிபார்ப்பு நிலையை உடனுக்குடன் அறிய.', 'BookCheck', 'https://eservices.tnpolice.gov.in/', 10, 1, 0, 1, NULL, NULL),
(11, 2, 'Character & Antecedent Verification', 'Character & Antecedent Verification', 'நடத்தை மற்றும் பின்னணி சரிபார்ப்பு', 'Submit verification requests for government, institutional or organizational character checks.', 'Submit verification requests for government, institutional or organizational character checks.', 'அரசு மற்றும் தனியார் நிறுவனங்களுக்கான நன்னடத்தை மற்றும் பின்னணி சரிபார்ப்பு கோரிக்கைகள்.', 'FileBadge', 'https://eservices.tnpolice.gov.in/', 11, 1, 0, 1, NULL, NULL),
(12, 2, 'Tenant Verification', 'Tenant Verification', 'வாடகைதாரர் சரிபார்ப்பு சேவை', 'Register tenant details with local police station for residential safety and verification.', 'Register tenant details with local police station for residential safety and verification.', 'குடியிருப்பு மற்றும் வாடகைதாரர்களின் விவரங்களை உள்ளூர் காவல் நிலையத்தில் பதிவு செய்தல்.', 'Home', 'https://eservices.tnpolice.gov.in/', 12, 1, 0, 1, NULL, NULL),
(13, 2, 'Domestic Help Verification', 'Domestic Help Verification', 'வீட்டுப் பணியாளர் சரிபார்ப்பு', 'Background verification for maids, cooks, drivers, security guards and domestic workers.', 'Background verification for maids, cooks, drivers, security guards and domestic workers.', 'வீட்டுப் பணியாளர்கள், ஓட்டுநர்கள் மற்றும் காவலாளிகளின் பின்னணி சரிபார்ப்பு சேவை.', 'UserCheck', 'https://eservices.tnpolice.gov.in/', 13, 1, 0, 1, NULL, NULL),
(14, 2, 'Employee / Servant Verification', 'Employee / Servant Verification', 'பணியாளர் சரிபார்ப்பு சேவை', 'Commercial and corporate background verification services for newly recruited personnel.', 'Commercial and corporate background verification services for newly recruited personnel.', 'நிறுவனங்கள் மற்றும் வணிக வளாகங்களில் பணிபுரியும் புதிய பணியாளர்களின் காவல் சரிபார்ப்பு.', 'Users', 'https://eservices.tnpolice.gov.in/', 14, 1, 0, 1, NULL, NULL),
(15, 3, 'Pay Traffic E-Challan', 'Pay Traffic E-Challan', 'போக்குவரத்து மின்-செல்லான் அபராதம் செலுத்துதல்', 'Pay traffic violation fines, check pending notices and download receipt on MoRTH portal.', 'Pay traffic violation fines, check pending notices and download receipt on MoRTH portal.', 'போக்குவரத்து அபராத தொகையை இணையவழியில் செலுத்தி உடனடி ரசீது பெற்றுக்கொள்ளவும்.', 'Receipt', 'https://echallan.parivahan.gov.in/', 15, 1, 1, 1, NULL, NULL),
(16, 3, 'Check E-Challan Status', 'Check E-Challan Status', 'போக்குவரத்து செல்லான் நிலை சரிபார்த்தல்', 'Check pending or settled traffic challans using vehicle registration number or DL number.', 'Check pending or settled traffic challans using vehicle registration number or DL number.', 'வாகன எண் அல்லது ஓட்டுநர் உரிம எண் மூலம் நிலுவையில் உள்ள செல்லான்களை சரிபார்க்க.', 'Search', 'https://echallan.parivahan.gov.in/', 16, 1, 0, 1, NULL, NULL),
(17, 3, 'Check Vehicle Details', 'Check Vehicle Details', 'வாகன விவரங்களை சரிபார்த்தல் (வாஹன்)', 'Verify vehicle registration, fitness, insurance and emission validity on Vahan citizen portal.', 'Verify vehicle registration, fitness, insurance and emission validity on Vahan citizen portal.', 'வாகனத்தின் பதிவு, காப்பீடு, தகுதிச் சான்றிதழ் விவரங்களை வாஹன் தளத்தில் சரிபார்க்க.', 'Car', 'https://vahan.parivahan.gov.in/', 17, 1, 0, 1, NULL, NULL),
(18, 3, 'Find Towed Vehicle', 'Find Towed Vehicle', 'காவல்துறையால் கொண்டு செல்லப்பட்ட வாகனம் அறிதல்', 'Locate vehicles towed by Chennai Traffic Police for no-parking or obstruction violations.', 'Locate vehicles towed by Chennai Traffic Police for no-parking or obstruction violations.', 'தவறான நிறுத்தத்தினால் கொண்டு செல்லப்பட்ட வாகனத்தின் தற்போதைய இருப்பிடத்தை கண்டறிய.', 'Truck', 'https://gctp.in/', 18, 1, 0, 1, NULL, NULL),
(19, 3, 'Traffic Diversion Information', 'Traffic Diversion Information', 'போக்குவரத்து மாற்றம் மற்றும் வழிகாட்டுதல்கள்', 'Live updates on road diversions, VIP movements, marathon routes and road repair advisories.', 'Live updates on road diversions, VIP movements, marathon routes and road repair advisories.', 'நகரின் தற்காலிக போக்குவரத்து மாற்றங்கள், விழாக்கள் மற்றும் மாற்றுப்பாதை தகவல்கள்.', 'Navigation', 'https://gctp.in/', 19, 1, 0, 1, NULL, NULL),
(20, 3, 'Road Safety Information', 'Road Safety Information', 'சாலை பாதுகாப்பு விழிப்புணர்வு வழிகாட்டி', 'Guidelines on helmet rules, seatbelts, speed limits, pedestrian safety and emergency roadside aid.', 'Guidelines on helmet rules, seatbelts, speed limits, pedestrian safety and emergency roadside aid.', 'சாலை விதிகள், தலைக்கவசம், வேகக் கட்டுப்பாடு மற்றும் விபத்து தவிர்ப்பு விழிப்புணர்வு குறிப்புகள்.', 'ShieldCheck', 'https://gctp.in/', 20, 1, 0, 1, NULL, NULL),
(21, 4, 'Senior Citizen Registration', 'Senior Citizen Registration', 'மூத்த குடிமக்கள் பாதுகாப்பு பதிவு', 'Register elderly citizens living alone with GCP beat officers for regular safety visits.', 'Register elderly citizens living alone with GCP beat officers for regular safety visits.', 'தனியாக வசிக்கும் முதியவர்கள் காவல்துறை பாதுகாப்பு மற்றும் வழக்கமான வருகைக்கு பதிவு செய்க.', 'UserRound', 'https://eservices.tnpolice.gov.in/', 21, 1, 0, 1, NULL, NULL),
(22, 4, 'Women Safety Assistance', 'Women Safety Assistance', 'பெண்கள் பாதுகாப்பு அவசர உதவி (1091)', '24/7 dedicated helpline, Pink Patrol mobile response, and crisis support for women in Chennai.', '24/7 dedicated helpline, Pink Patrol mobile response, and crisis support for women in Chennai.', 'பெண்களுக்கான 24 மணி நேர பிரத்யேக அவசர உதவி எண் 1091 மற்றும் பிங்க் ரோந்து படை உதவி.', 'Shield', 'https://eservices.tnpolice.gov.in/', 22, 1, 1, 1, NULL, NULL),
(23, 4, 'Child Safety Assistance', 'Child Safety Assistance', 'குழந்தைகள் பாதுகாப்பு உதவி (1098)', 'Support and reporting channel for children in distress, missing minors and child welfare assistance.', 'Support and reporting channel for children in distress, missing minors and child welfare assistance.', 'குழந்தைகள் பாதுகாப்பு, உதவி தேவைப்படும் சிறுவர்கள் மீட்பு மற்றும் சைல்டுலைன் 1098 சேவை.', 'HeartHandshake', 'https://eservices.tnpolice.gov.in/', 23, 1, 0, 1, NULL, NULL),
(24, 4, 'Emergency Contact Directory', 'Emergency Contact Directory', 'அவசர உதவி எண்கள் மற்றும் கட்டுப்பாட்டு அறை', 'Direct helpline numbers for Police (112 / 100), Cyber Crime (1930) and all GCP control rooms.', 'Direct helpline numbers for Police (112 / 100), Cyber Crime (1930) and all GCP control rooms.', 'காவல்துறை கட்டுப்பாட்டு அறை 112, 100 மற்றும் 1930 உள்ளிட்ட அவசர உதவி எண்களின் தொகுப்பு.', 'PhoneCall', '/stations', 24, 1, 0, 0, NULL, NULL),
(25, 4, 'Police Station Finder', 'Police Station Finder', 'அருகிலுள்ள காவல் நிலைய வழிகாட்டி', 'Directory of all 221 police stations across North, South, East, West and Central Chennai.', 'Directory of all 221 police stations across North, South, East, West and Central Chennai.', 'சென்னை பெருநகர காவல் எல்லைக்குட்பட்ட 221 காவல் நிலையங்களின் முகவரி மற்றும் தொலைபேசி எண்கள்.', 'MapPin', '/stations', 25, 1, 0, 0, NULL, NULL),
(26, 4, 'Nearest Police Station / GPS', 'Nearest Police Station / GPS', 'ஜி.பி.எஸ் மூலம் அருகிலுள்ள காவல் நிலையம்', 'Automatic GPS geolocation tool to pinpoint your jurisdiction police station and contact details.', 'Automatic GPS geolocation tool to pinpoint your jurisdiction police station and contact details.', 'உங்கள் தற்போதைய ஜி.பி.எஸ் இருப்பிடம் மூலம் எல்லைக்குட்பட்ட காவல் நிலையத்தை அறியும் வசதி.', 'Compass', '/stations', 26, 1, 0, 0, NULL, NULL),
(27, 5, 'Loudspeaker Permission', 'Loudspeaker Permission', 'ஒலிபெருக்கி பயன்பாட்டு அனுமதி விண்ணப்பம்', 'Online application for regulatory permission to operate loudspeakers for cultural or religious events.', 'Online application for regulatory permission to operate loudspeakers for cultural or religious events.', 'பொது மற்றும் சமய விழாக்களில் ஒலிபெருக்கி பயன்படுத்துவதற்கான காவல் அனுமதி விண்ணப்பம்.', 'Megaphone', 'https://eservices.tnpolice.gov.in/', 27, 1, 0, 1, NULL, NULL),
(28, 5, 'Event / Public Meeting Permission', 'Event / Public Meeting Permission', 'பொதுக்கூட்டம் மற்றும் நிகழ்வு அனுமதி', 'Apply for police clearance and bandobast arrangements for rallies, public meetings and concerts.', 'Apply for police clearance and bandobast arrangements for rallies, public meetings and concerts.', 'பொதுக்கூட்டங்கள், பேரணிகள் மற்றும் பொது நிகழ்ச்சிகள் நடத்துவதற்கான முன் அனுமதி கோரிக்கை.', 'CalendarCheck', 'https://eservices.tnpolice.gov.in/', 28, 1, 0, 1, NULL, NULL),
(29, 5, 'Film / Photography Permission', 'Film / Photography Permission', 'திரைப்பட / புகைப்பட படப்பிடிப்பு அனுமதி', 'Single-window permission requests for commercial movie, TV and documentary shooting in Chennai.', 'Single-window permission requests for commercial movie, TV and documentary shooting in Chennai.', 'சென்னை நகரின் பொது இடங்களில் திரைப்படம் மற்றும் தொலைக்காட்சி படப்பிடிப்பு நடத்துவதற்கான அனுமதி.', 'Video', 'https://eservices.tnpolice.gov.in/', 29, 1, 0, 1, NULL, NULL),
(30, 5, 'Arms Licence / Renewal Information', 'Arms Licence / Renewal Information', 'துப்பாக்கி உரிமம் / புதுப்பித்தல் விவரங்கள்', 'Guidelines, eligibility criteria, documentation checklists and renewal services for firearm licenses.', 'Guidelines, eligibility criteria, documentation checklists and renewal services for firearm licenses.', 'துப்பாக்கி உரிமம் பெறுதல், புதுப்பித்தல் மற்றும் ஆவண சரிபார்ப்பு குறித்த விதிமுறைகள்.', 'FileSpreadsheet', 'https://eservices.tnpolice.gov.in/', 30, 1, 0, 1, NULL, NULL);
