INSERT INTO `superadmin_config` (`id`, `footer_config`) VALUES
(NULL, '{"logo":"/images/gcp_logo.png","website_name_en":"Greater Chennai Police","website_name_ta":"சென்னை பெருநகர காவல்","description_en":"Official news platform of Greater Chennai Police, providing 24/7 updates on public safety, cyber alerts, and community-centered policing initiatives.","description_ta":"சென்னையின் முன்னணி சட்டம் ஒழுங்கு, குற்றப் புலனாய்வு மற்றும் மக்கள் விழிப்புணர்வு செய்திகளை உடனுக்குடன் வழங்கும் அதிகாரப்பூர்வ செய்தி ஊடகம்.","copyright_text_en":"© 2026 Greater Chennai Police. All rights reserved.","copyright_text_ta":"© 2026 சென்னை பெருநகர காவல். அனைத்து உரிமைகளும் பாதுகாக்கப்பட்டவை.","developer_credit_en":"Website Content developed, Managed and Content owned by: Greater Chennai Police, Chennai \\nDesigned, Developed and Hosted by: MCC-MRF Innovation Park","developer_credit_ta":"இணையதள உள்ளடக்கம் உருவாக்கப்பட்டது, நிர்வகிக்கப்பட்டது மற்றும் உடைமையானது: பெரிய சென்னை போலீஸ், சென்னை \\nவடிவமைப்பு, உருவாக்கம் மற்றும் ஹோஸ்டிங்: MCC-MRF இனோவேஷன் பார்க்","address_en":"Commissioner Office, Greater Chennai Police, Vepery, Chennai - 600007","address_ta":"காவல் ஆணையர் அலுவலகம், சென்னை பெருநகர காவல், வேப்பேரி, சென்னை - 600007","phone":"044-23452300","email":"cop@gcp.tn.gov.in","google_map_link":"https://maps.google.com/?q=Commissioner+Office+Greater+Chennai+Police+Vepery","social_facebook":"https://facebook.com","social_twitter":"https://twitter.com","social_youtube":"https://youtube.com","social_instagram":"https://instagram.com","background_image":"","background_color":"#1e40af","text_color":"#ffffff","footer_visible":true,"quick_links":[{"id":"ql1","label_en":"Home","label_ta":"முகப்பு","url":"/","target_blank":false,"active":true,"order_index":1},{"id":"ql2","label_en":"Citizen Services","label_ta":"குடிமக்கள் சேவைகள்","url":"/citizen-services","target_blank":false,"active":true,"order_index":2},{"id":"ql3","label_en":"Police Stations","label_ta":"காவல் நிலையங்கள்","url":"/stations","target_blank":false,"active":true,"order_index":3}],"government_links":[{"id":"gl1","label_en":"Tamil Nadu Government","label_ta":"தமிழ்நாடு அரசு","url":"https://www.tn.gov.in","target_blank":true,"active":true,"order_index":1}]}');
